export type WhoFirstPhase = 'LOBBY' | 'COUNTDOWN' | 'ACTIVE' | 'ROUND_RESULT' | 'FINISHED';
export type WhoFirstGameActionType = 'START_COUNTDOWN' | 'SET_ACTIVE' | 'PRESS_BUTTON' | 'NEXT_ROUND' | 'END_GAME';
export interface WhoFirstPressRecord {
    socketId: string;
    timestamp: number;
    reactionTimeMs?: number;
    isPenalty: boolean;
}
export interface WhoFirstState {
    phase: WhoFirstPhase;
    countdownStartTime?: number;
    countdownDurationMs?: number;
    activeStartTime?: number;
    presses: WhoFirstPressRecord[];
    currentRound: number;
    maxRounds: number;
}
